  "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  // LOCAL: sqlite  |  RAILWAY PRODUCTION: switch back to \"postgresql\"\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ─── Enums (SQLite: stored as strings) ──────────────────────────────────────\n\n// User role\n// DISTRIBUTOR: uploads work, reviews quotes, gives feedback\n// PROVIDER: quotes, works on tasks, submits deliverables\nmodel User {\n  id           String   @id @default(cuid())\n  email        String   @unique\n  passwordHash String\n  name         String\n  role         String // \"DISTRIBUTOR\" | \"PROVIDER\"\n  createdAt    DateTime @default(now())\n\n  tasks    Task[]     @relation(\"CreatedTasks\")\n  quotes   Quote[]\n  messages Message[]\n  files    TaskFile[]\n}\n\n// Task status lifecycle\n// PENDING_QUOTE → QUOTED → IN_PROGRESS → SUBMITTED → REVISION → COMPLETED\nmodel Task {\n  id                String    @id @default(cuid())\n  title             String\n  status            String    @default(\"PENDING_QUOTE\")\n  taskType          String // \"ESSAY\" | \"POWERPOINT\" | \"SPSS\" | \"QUESTIONNAIRE\" | \"LONG_TERM\" | \"MIXED\"\n  wordCount         Int?\n  deadline          DateTime?\n  university        String?\n  aiDescription     String? // LLM-generated description\n  rawPrompt         String? // original distributor description\n  revisionRound     Int       @default(0)\n  seenByDistributor Boolean   @default(true) // false = new update not yet seen by distributor\n  createdAt         DateTime  @default(now())\n  updatedAt         DateTime  @updatedAt\n\n  createdById String\n  createdBy   User   @relation(\"CreatedTasks\", fields: [createdById], references: [id])\n\n  files     TaskFile[]\n  quotes    Quote[]\n  revisions Revision[]\n  messages  Message[]\n  stages    TaskStage[]\n}\n\n// Files attached to a task (stored on Cloudinary)\nmodel TaskFile {\n  id          String   @id @default(cuid())\n  taskId      String\n  driveFileId String\n  driveUrl    String\n  fileName    String\n  mimeType    String\n  stageName   String? // null = original upload; set for stage deliverables\n  uploadedAt  DateTime @default(now())\n\n  uploadedById String\n  uploadedBy   User   @relation(fields: [uploadedById], references: [id])\n  task         Task   @relation(fields: [taskId], references: [id], onDelete: Cascade)\n}\n\n// Quote submitted by a provider\nmodel Quote {\n  id         String   @id @default(cuid())\n  taskId     String\n  providerId String\n  amount     Float\n  currency   String   @default(\"USD\")\n  note       String?\n  status     String   @default(\"PENDING\") // \"PENDING\" | \"ACCEPTED\" | \"REJECTED\"\n  createdAt  DateTime @default(now())\n\n  task     Task @relation(fields: [taskId], references: [id], onDelete: Cascade)\n  provider User @relation(fields: [providerId], references: [id])\n}\n\n// Revision request from distributor\nmodel Revision {\n  id          String   @id @default(cuid())\n  taskId      String\n  round       Int\n  feedback    String\n  requestedAt DateTime @default(now())\n\n  task Task @relation(fields: [taskId], references: [id], onDelete: Cascade)\n}\n\n// Stage tracking for long-term multi-stage tasks\nmodel TaskStage {\n  id      String    @id @default(cuid())\n  taskId  String\n  name    String // e.g. \"Abstract\", \"Draft\", \"Full Paper\"\n  status  String    @default(\"PENDING\") // \"PENDING\" | \"IN_PROGRESS\" | \"SUBMITTED\" | \"APPROVED\"\n  dueDate DateTime?\n  order   Int\n\n  task Task @relation(fields: [taskId], references: [id], onDelete: Cascade)\n}\n\n// In-task messaging thread between stakeholders\nmodel Message {\n  id        String   @id @default(cuid())\n  taskId    String\n  senderId  String\n  body      String\n  createdAt DateTime @default(now())\n\n  task   Task @relation(fields: [taskId], references: [id], onDelete: Cascade)\n  sender User @relation(fields: [senderId], references: [id])\n}\n",
